cat > /app/hierarchical_model.stan <<'EOF'
data {
  int<lower=1> K;              // number of groups
  array[K] int<lower=0> y;     // number of successes in each group
  array[K] int<lower=1> n;     // number of trials in each group
}
parameters {
  vector<lower=0>[K] theta;    // group-level success probabilities
  vector<lower=0>[2] phi;      // phi[1] = alpha, phi[2] = beta (both > 0)
}
generated quantities {
  real alpha = phi[1];         // Beta distribution shape parameter 1
  real beta  = phi[2];         // Beta distribution shape parameter 2
}
model {
  // prior: p(alpha, beta) proportional to (alpha + beta)^(-5/2)
  target += -2.5 * log(phi[1] + phi[2]);

  for (i in 1:K) {
    y[i] ~ binomial(n[i], theta[i]);
    theta[i] ~ beta(phi[1], phi[2]);
  }
}
EOF
